3]\nY = diff[1:]   # [171, 5373, -585]\n\n# Add intercept\nn = len(X)\nsum_x = sum(X)\nsum_y = sum(Y)\nsum_xy = sum(X[i]*Y[i] for i in range(n))\nsum_xx = sum(x*x for x in X)\n\n# OLS estimates\n# c = (sum_y - phi * sum_x) / n\n# phi = (n*sum_xy - sum_x*sum_y) / (n*sum_xx - sum_x*sum_x)\n\ndenominator = n*sum_xx - sum_x*sum_x\nphi = (n*sum_xy - sum_x*sum_y) / denominator\nc = (sum_y - phi*sum_x) / n\n\nprint(f\"\\nAR(1) coefficient (phi): {phi}\")\nprint(f\"Intercept (c): {c}\")\n\n# Forecast: y[n] = y[n-1] + c + phi * diff[n-1]\n# which is: y_1983 = y_1982 + c + phi * (y_1982 - y_1981)\n\ny_1982 = y[-1]       # 64270\ny_1981 = y[-2]       # 64855\ndiff_last = y_1982 - y_1981  # -585\n\nforecast_diff = c + phi * diff_last\nforecast_1983 = y_1982 + forecast_diff\n\nprint(f\"\\nLast diff: {diff_last}\")\nprint(f\"Forecast diff: {forecast_diff}\")\nprint(f\"Forecast for 1983: {forecast_1983}\")\n\n# Round to nearest whole number\nforecast_rounded = round(forecast_1983)\nprint(f\"Rounded forecast: {forecast_rounded}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
