ff_ols = c_ols + phi_ols * diff_last\nforecast_ols = y_1982 + forecast_diff_ols\nprint(f\"Forecast (OLS): {forecast_ols}\")\nprint(f\"Rounded: {round(forecast_ols)}\")\n\n# Method 3: Simple AR(1) on differences with zero mean (no constant)\n# This is what you'd get with a specific setting\nphi_simple = gamma_1 / gamma_0  # This is the same phi\n# For zero-mean model: forecast diff = phi * last_diff\nforecast_diff_simple = phi_simple * diff_last\nforecast_simple = y_1982 + forecast_diff_simple\nprint(f\"\\nSimple (no constant):\")\nprint(f\"phi = {phi_simple}\")\nprint(f\"Forecast (no constant): {forecast_simple}\")\nprint(f\"Rounded: {round(forecast_simple)}\")\n\nprint(\"\\n=== SUMMARY ===\")\nprint(f\"Yule-Walker with constant: {round(forecast_yw)}\")\nprint(f\"OLS with constant: {round(forecast_ols)}\")\nprint(f\"Simple (no constant): {round(forecast_simple)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
