ommercial banks\n        \n        # Let's find the cell containing \"commercial banks\"\n        for i, cell in enumerate(cells):\n            if 'commercial banks' in cell.lower():\n                print(f\"Year {year}: Found commercial banks header at position {i}\")\n                # The value should be in the next cell\n                if i+1 < len(cells):\n                    value_match = re.search(r'>(\\d[\\d,]*)', cells[i+1])\n                    if value_match:\n                        value = int(value_match.group(1).replace(',', ''))\n                        results[year] = value\n                        print(f\"  Value: {value}\")\n                break\n\nprint(\"\\n=== Summary ===\")\nfor year in sorted(results.keys()):\n    print(f\"March 31, {year}: {results[year]} million\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
